Compose_Comment_message_-_Results_-_Acco.inputs:
Found below information from OpenCTI for @{items('For_each_Account_in_Entity')?['Name']} (Account)
----------------------------------------------------------------------
Indicator Name: @{items('For_each_indictor_info_on_Account')?['node']?['name']}
Indicator Type: @{if(empty(items('For_each_indictor_info_on_Account')?['node']?['x_opencti_main_observable_type']), 'Unknown', items('For_each_indictor_info_on_Account')?['node']?['x_opencti_main_observable_type'])}
OpenCTI Scope: @{coalesce(items('For_each_indictor_info_on_Account')?['node']?['x_opencti_score'], 0)}
Entity Type: @{if(empty(items('For_each_indictor_info_on_Account')?['node']?['entity_type']), 'Unknown', items('For_each_indictor_info_on_Account')?['node']?['entity_type'])}
Description: @{if(empty(items('For_each_indictor_info_on_Account')?['node']?['description']), 'No description', items('For_each_indictor_info_on_Account')?['node']?['description'])}
Created By: @{if(empty(items('For_each_indictor_info_on_Account')?['node']?['createdBy']?['name']), 'Unknown', items('For_each_indictor_info_on_Account')?['node']?['createdBy']?['name'])}
----------------------------------------------------------------------

body.query:
query {
  indicators(
    filters: {
      mode: and
      filters: [
        {
          key: "name"
          operator: eq
          values: ["@{items('For_each_Account_in_Entity')?['Name']}"]
        }
      ]
      filterGroups: []
    }
    first: 50
  ) {
    edges {
      node {
        name
        entity_type
        indicator_types
        createdBy {
          name
        }
        description
        x_opencti_score
        x_opencti_main_observable_type
      }
    }
  }
}

